# Compares the prep_csv_*.csv files regenerated by 01_preparation_function.R with the deposited copies.
import csv, hashlib, json, sys
S = "/workspace/audit_runs/10_6MLKJZ/A"
out = {}
for s in ["rh", "uhh", "hsvn", "civic"]:
    a = f"{S}/deposited_prep/prep_csv_{s}.csv"; b = f"{S}/run/data/conjoint_data/prep_data/prep_csv_{s}.csv"
    ra = list(csv.reader(open(a, encoding="utf-8", errors="replace"))); rb = list(csv.reader(open(b, encoding="utf-8", errors="replace")))
    out[s] = {"sha256_deposited": hashlib.sha256(open(a, "rb").read()).hexdigest(), "sha256_regenerated": hashlib.sha256(open(b, "rb").read()).hexdigest(),
              "rows_deposited": len(ra), "rows_regenerated": len(rb), "cols_deposited": len(ra[0]), "cols_regenerated": len(rb[0]),
              "parsed_cells_identical": ra == rb,
              "ResponseIds_identical": sorted(r[ra[0].index("ResponseId")] for r in ra[1:] if len(r) > ra[0].index("ResponseId")) == sorted(r[rb[0].index("ResponseId")] for r in rb[1:] if len(r) > rb[0].index("ResponseId"))}
json.dump(out, open(sys.argv[1], "w"), indent=1); print(json.dumps(out, indent=1))
